import {
  isProgramError,
  type Address,
  type SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM,
  type SolanaError,
} from "@solana/kit";
import { MINTER_PROGRAM_ADDRESS } from "../programs";

/** Unauthorized: Unauthorized */
export const MINTER_ERROR__UNAUTHORIZED = 0x1770; // 6000
/** ArithmeticOverflow: Arithmetic overflow */
export const MINTER_ERROR__ARITHMETIC_OVERFLOW = 0x1771; // 6001

export type MinterError =
  | typeof MINTER_ERROR__ARITHMETIC_OVERFLOW
  | typeof MINTER_ERROR__UNAUTHORIZED;

let minterErrorMessages: Record<MinterError, string> | undefined;
if (process.env.NODE_ENV !== "production") {
  minterErrorMessages = {
    [MINTER_ERROR__ARITHMETIC_OVERFLOW]: `Arithmetic overflow`,
    [MINTER_ERROR__UNAUTHORIZED]: `Unauthorized`,
  };
}

export function getMinterErrorMessage(code: MinterError): string {
  if (process.env.NODE_ENV !== "production") {
    return (minterErrorMessages as Record<MinterError, string>)[code];
  }

  return "Error message not available in production bundles.";
}

export function isMinterError<TProgramErrorCode extends MinterError>(
  error: unknown,
  transactionMessage: {
    instructions: Record<number, { programAddress: Address }>;
  },
  code?: TProgramErrorCode,
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
  Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
  return isProgramError<TProgramErrorCode>(
    error,
    transactionMessage,
    MINTER_PROGRAM_ADDRESS,
    code,
  );
}
